def shout(func):
    def wrapper():
        print("before")
        func()
        print("after")
    return wrapper

@shout
def hello():
    print("Hello")

hello()

import functools

def log(func):
    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        result = func(*args, **kwargs)
        print(func.__name__, args, "->", result)
        return result
    return wrapper

@log
def add(a, b):
    return a + b

print(add(2, 3))
print(add.__name__)

